import { CheckProfanityResult, Language, Filter } from 'glin-profanity';
export { CheckProfanityResult, FilterConfig, Language } from 'glin-profanity';

/**
 * OpenClaw Hooks - Automatic Message Moderation
 *
 * Hooks allow automatic interception and processing of messages
 * before they are sent or after they are received.
 *
 * The profanity guard hook automatically moderates all messages
 * across WhatsApp, Telegram, Discord, Slack, iMessage, etc.
 *
 * @example
 * ```typescript
 * import { createProfanityGuard } from 'openclaw-profanity/hooks';
 *
 * const guard = createProfanityGuard({
 *   mode: 'moderate',
 *   blockProfanity: false,
 *   censorProfanity: true,
 * });
 *
 * // In your hook
 * export default guard;
 * ```
 *
 * @remarks
 * Compatible with OpenClaw, Moltbot (legacy), and Clawdbot (legacy).
 *
 * @packageDocumentation
 */

/**
 * Moderation mode determines strictness level
 */
type ModerationMode = 'strict' | 'moderate' | 'lenient';
/**
 * Hook action to take when profanity is detected
 */
type HookAction = 'block' | 'censor' | 'warn' | 'log';
/**
 * Profanity guard configuration
 */
interface ProfanityGuardConfig {
    /** Moderation strictness level */
    mode?: ModerationMode;
    /** Languages to check (default: ['english']) */
    languages?: Language[];
    /** Block messages with profanity */
    blockProfanity?: boolean;
    /** Automatically censor profanity */
    censorProfanity?: boolean;
    /** Replacement string for censoring */
    censorReplacement?: string;
    /** Log all profanity incidents */
    logIncidents?: boolean;
    /** Custom callback when profanity is detected */
    onProfanityDetected?: (result: ProfanityIncident) => void | Promise<void>;
    /** Whitelist specific words */
    whitelist?: string[];
    /** Channels/platforms to skip */
    skipChannels?: string[];
}
/**
 * Profanity incident information
 */
interface ProfanityIncident {
    /** Original message */
    originalMessage: string;
    /** Processed/censored message */
    processedMessage?: string;
    /** Profane words found */
    profaneWords: string[];
    /** Action taken */
    action: HookAction;
    /** Timestamp */
    timestamp: Date;
    /** Source channel (if available) */
    channel?: string;
    /** User ID (if available) */
    userId?: string;
    /** Full check result */
    checkResult: CheckProfanityResult;
}
/**
 * Hook message context
 */
interface HookMessageContext {
    /** Message content */
    message: string;
    /** Source channel/platform */
    channel?: string;
    /** User identifier */
    userId?: string;
    /** Direction: incoming or outgoing */
    direction?: 'incoming' | 'outgoing';
    /** Additional metadata */
    metadata?: Record<string, unknown>;
}
/**
 * Hook result
 */
interface HookResult {
    /** Whether to proceed with the message */
    proceed: boolean;
    /** Modified message (if any) */
    message?: string;
    /** Reason for blocking (if blocked) */
    reason?: string;
    /** Incident details */
    incident?: ProfanityIncident;
}
/**
 * Create a profanity guard hook
 *
 * @example
 * ```typescript
 * // Basic usage
 * const guard = createProfanityGuard();
 *
 * // Strict mode that blocks profanity
 * const strictGuard = createProfanityGuard({
 *   mode: 'strict',
 *   blockProfanity: true,
 * });
 *
 * // Moderate mode that censors
 * const censorGuard = createProfanityGuard({
 *   mode: 'moderate',
 *   censorProfanity: true,
 *   censorReplacement: '[CENSORED]',
 * });
 *
 * // Multi-language
 * const multiLangGuard = createProfanityGuard({
 *   languages: ['english', 'spanish', 'french'],
 * });
 * ```
 */
declare function createProfanityGuard(config?: ProfanityGuardConfig): {
    /** Process a message */
    processMessage: (context: HookMessageContext) => Promise<HookResult>;
    /** Hook handler for OpenClaw */
    handler: (message: string, context?: Partial<HookMessageContext>) => Promise<HookResult>;
    /** Get incident log */
    getIncidentLog: () => ProfanityIncident[];
    /** Clear incident log */
    clearIncidentLog: () => void;
    /** Get incident count */
    getIncidentCount: () => number;
    /** Get filter instance */
    getFilter: () => Filter;
    /** Update whitelist (note: requires recreating the filter) */
    addToWhitelist: (words: string[]) => void;
    /** Get configuration */
    getConfig: () => {
        mode: ModerationMode;
        languages: Language[];
        blockProfanity: boolean;
        censorProfanity: boolean;
        censorReplacement: string;
        logIncidents: boolean;
        whitelist: string[];
        skipChannels: string[];
    };
};
/**
 * Quick guard - Simple one-function check
 *
 * @example
 * ```typescript
 * const result = quickGuard('Hello world');
 * if (!result.proceed) {
 *   console.log('Message blocked:', result.reason);
 * }
 * ```
 */
declare function quickGuard(message: string, options?: {
    block?: boolean;
    censor?: boolean;
    languages?: Language[];
}): HookResult;
/**
 * Default export for OpenClaw hook discovery
 *
 * @remarks
 * This creates a moderate-mode guard with censoring enabled,
 * which is a safe default for most platforms.
 */
declare const _default: {
    /** Process a message */
    processMessage: (context: HookMessageContext) => Promise<HookResult>;
    /** Hook handler for OpenClaw */
    handler: (message: string, context?: Partial<HookMessageContext>) => Promise<HookResult>;
    /** Get incident log */
    getIncidentLog: () => ProfanityIncident[];
    /** Clear incident log */
    clearIncidentLog: () => void;
    /** Get incident count */
    getIncidentCount: () => number;
    /** Get filter instance */
    getFilter: () => Filter;
    /** Update whitelist (note: requires recreating the filter) */
    addToWhitelist: (words: string[]) => void;
    /** Get configuration */
    getConfig: () => {
        mode: ModerationMode;
        languages: Language[];
        blockProfanity: boolean;
        censorProfanity: boolean;
        censorReplacement: string;
        logIncidents: boolean;
        whitelist: string[];
        skipChannels: string[];
    };
};

export { type HookAction, type HookMessageContext, type HookResult, type ModerationMode, type ProfanityGuardConfig, type ProfanityIncident, createProfanityGuard, _default as default, quickGuard };
